        value = payload.get(field)
        if spec['type'] == 'array':
            values = value if isinstance(value, list) else []
            allowed = spec['items']['enum']
            result[field] = list(dict.fromkeys(v for v in values if isinstance(v, str) and v in allowed))[:spec.get('maxItems', len(allowed))]
        elif field.endswith(('__ge', '__le')):
            n = number(value)
            if n is not None and ('rate' in field) and n > 1:
                n = None
            result[field] = render(n) if n is not None else None
        else:
            value = value.strip() if isinstance(value, str) else None
